-- LOCAL TEST ONLY: minimal Supabase-like roles + the base tables as they exist in production (inferred from the data snapshot).
do $$ begin
  create role anon nologin; exception when duplicate_object then null; end $$;
do $$ begin create role authenticated nologin; exception when duplicate_object then null; end $$;
create schema if not exists auth;
create or replace function auth.uid() returns uuid language sql stable as $$ select coalesce(nullif(current_setting('request.jwt.claim.sub', true), ''), nullif(current_setting('request.jwt.claims', true), '')::jsonb->>'sub')::uuid $$;
grant usage on schema public, auth to anon, authenticated;
create table entities (id text primary key, name text not null, sort_order int default 0, created_at timestamptz default now());
create table ventures (id bigint primary key, entity_id text, name text, notes text, color text, is_active boolean default true, sort_order int default 0, created_at timestamptz default now());
create table accounts (id bigint generated by default as identity primary key, created_at timestamptz default now(), name text, type text, balance numeric(14,2) default 0, credit_limit numeric(14,2) default 0, minimum_payment numeric(14,2) default 0, payment_due_day int, next_payment_due_date date, payment_category_id bigint, entity_id text default 'personal');
create table category_groups (id bigint generated by default as identity primary key, name text, sort_order int, entity_id text);
create table categories (id bigint generated by default as identity primary key, group_id bigint, name text, target_amount numeric(14,2) default 0, target_period text, sort_order int, emoji text, target_type text, due_date date, is_repeating boolean default false, end_date date, notes text, assigned_amount numeric(14,2) default 0, is_debt boolean default false, balance numeric(14,2) default 0, is_asap boolean default false, is_hidden boolean default false, budgeted_amount numeric(14,2) default 0, entity_id text, venture_id bigint, purpose text, bill_subtype text, debt_apr numeric, debt_min_payment numeric, linked_account_id bigint);
create table transactions (id bigint generated by default as identity primary key, created_at timestamptz default now(), date date, amount numeric(14,2), payee text, category_id bigint, account_id bigint, to_account_id bigint, type text, purchase_rating text, notes text, entity_id text, venture_id bigint, linked_transaction_id bigint, owner_flow text);
create table transaction_splits (id bigint generated by default as identity primary key, transaction_id bigint references transactions(id) on delete cascade, category_id bigint references categories(id), amount numeric(12,2), sort_order int default 0);
create table projected_income (id bigint generated by default as identity primary key, created_at timestamptz default now(), label text, amount numeric(12,2), expected_date date, account_id bigint, category_id bigint, status text default 'pending', source_type text, is_repeating boolean default false, repeat_period text, notes text, transaction_id bigint, received_at timestamptz, certainty text, entity_id text, venture_id bigint);
create table transaction_attachments (id bigint generated by default as identity primary key, transaction_id bigint);
-- permissive legacy policies, as production has today
do $$ declare t text; begin foreach t in array array['entities','ventures','accounts','category_groups','categories','transactions','transaction_splits','projected_income','transaction_attachments'] loop
 execute format('alter table %I enable row level security', t);
 execute format('create policy legacy_all on %I for all to anon, authenticated using (true) with check (true)', t);
 execute format('grant all on %I to anon, authenticated', t); end loop; end $$;
-- foreign keys the real schema has (needed so PostgREST embeds like accounts!account_id(...) resolve in tests)
alter table projected_income add foreign key (account_id) references accounts(id), add foreign key (category_id) references categories(id), add foreign key (venture_id) references ventures(id);
alter table categories add foreign key (venture_id) references ventures(id);
alter table transactions add foreign key (account_id) references accounts(id), add foreign key (to_account_id) references accounts(id), add foreign key (category_id) references categories(id), add foreign key (venture_id) references ventures(id);
